import lzma

# Check filter option keys for lzma2
# According to Python docs, LZMA2 filter dict options: id, preset, dict_size, lc, lp, pb, mode, nice_len, mf, depth
# Let's try compress with dict_size etc
try:
    f = {"id": lzma.FILTER_LZMA2, "dict_size": 8*1024*1024, "lc":3, "lp":0, "pb":2, "mode": lzma.MODE_NORMAL, "nice_len":64, "mf": lzma.MF_BT4, "depth":0, "preset":6}
    data = lzma.compress(b"hello world\n"*100, format=lzma.FORMAT_XZ, filters=[f])
    print("compress with dict_size etc ok len", len(data))
except Exception as e:
    print("failed", e)
    import traceback; traceback.print_exc()

# Try with preset only
try:
    f = {"id": lzma.FILTER_LZMA2, "preset": 6}
    data = lzma.compress(b"hello\n", format=lzma.FORMAT_XZ, filters=[f])
    print("preset 6 ok")
except Exception as e:
    print(e)

# Try with extreme?
# Python's preset can be ORed with PRESET_EXTREME
try:
    f = {"id": lzma.FILTER_LZMA2, "preset": 6 | lzma.PRESET_EXTREME}
    data = lzma.compress(b"hello\n", format=lzma.FORMAT_XZ, filters=[f])
    print("preset extreme ok")
except Exception as e:
    print(e)

# Test BCJ + LZMA2
try:
    filters = [{"id": lzma.FILTER_X86}, {"id": lzma.FILTER_LZMA2, "preset":6}]
    data = lzma.compress(b"hello\n", format=lzma.FORMAT_XZ, filters=filters)
    print("x86+lzma2 ok")
except Exception as e:
    print(e)

# Test delta + lzma2
try:
    filters = [{"id": lzma.FILTER_DELTA, "dist":1}, {"id": lzma.FILTER_LZMA2, "preset":6}]
    data = lzma.compress(b"hello\n", format=lzma.FORMAT_XZ, filters=filters)
    print("delta ok")
except Exception as e:
    print(e)
    import traceback; traceback.print_exc()

# Test lzma1 filter for alone format
try:
    f = {"id": lzma.FILTER_LZMA1, "preset":6}
    data = lzma.compress(b"hello\n", format=lzma.FORMAT_ALONE, filters=[f])
    print("lzma1 alone ok len", len(data))
    # decompress
    print(lzma.decompress(data))
except Exception as e:
    print("lzma1 alone failed", e)

# Test raw
try:
    f = {"id": lzma.FILTER_LZMA2, "preset":6}
    c = lzma.LZMACompressor(format=lzma.FORMAT_RAW, filters=[f])
    comp = c.compress(b"hello\n") + c.flush()
    print("raw compress ok", comp)
    d = lzma.LZMADecompressor(format=lzma.FORMAT_RAW, filters=[f])
    decom = d.decompress(comp)
    print("raw decompress", decom)
except Exception as e:
    print("raw failed", e)
    import traceback; traceback.print_exc()

