            if has_uncomp:
                flags_str += "u"
            if flags_str == "":
                flags_str = "--"
            comp_data_offset = block_offset + hdr_size
            check_offset = comp_data_offset + padded_comp
            check_val = data[check_offset:check_offset+check_size]
            check_val_hex = check_val.hex()
            blocks.append({
                'header_size': hdr_size,
                'comp_size': comp_size,
                'unpadded': unpadded,
                'uncomp': uncomp,
                'total_size': total_block_size,
                'comp_offset': block_offset,
                'uncomp_offset': uncomp_offset_stream,
                'check_val': check_val,
                'check_val_hex': check_val_hex,
                'filter_str': ",".join(filter_descs) if filter_descs else "--lzma2=dict=8MiB",
                'flags_str': flags_str,
                'mem_usage': 9,
            })
            uncomp_offset_stream += uncomp
            block_offset += total_block_size
        comp_size_stream = f_start + 12 - offset
        uncomp_size_stream = sum(r[1] for r in records)
        streams.append({
            'blocks': blocks,
            'comp_offset': offset,
            'uncomp_offset': total_uncomp,
            'comp_size': comp_size_stream,
            'uncomp_size': uncomp_size_stream,
            'check_type': check_type_id,
            'check_name': check_name,
            'check_size': check_size,
            'index_offset': idx_start,
            'footer_offset': f_start,
        })
        total_uncomp += uncomp_size_stream
        offset = f_start + 12
    return {
        'streams': streams,
        'file_size': file_size,
        'total_blocks': sum(len(s['blocks']) for s in streams),
        'total_streams': len(streams),
        'total_uncomp': total_uncomp,
        'total_stream_padding': total_stream_padding,
        'check_name': streams[0]['check_name'] if streams else "None",
    }

def format_size_l(size):
    if size < 10*1024:
        return f"{size} B"
    if size < 1024*1024:
        return f"{size/1024:.1f} KiB"
    if size < 1024*1024*1024:
        return f"{size/(1024*1024):.1f} MiB"
    return f"{size/(1024*1024*1024):.1f} GiB"

def format_ratio(comp, uncomp):
    if uncomp == 0:
        return "---"
    r = comp / uncomp
    if r > 9.999:
        return "---"
    return f"{r:.3f}"

def format_ratio_verbose(comp, uncomp):
    if uncomp == 0:
        return "---"
    r = comp / uncomp
    if r > 9.999:
        return "> 9.999"
    return f"{r:.3f}"

def parse_size_str(s):
    s = s.strip()
    if s.endswith('%'):
        return s
    for suf, mult in [("GiB",1024**3), ("MiB",1024**2), ("KiB",1024), ("G",10**9), ("M",10**6), ("K",10**3)]:
        if s.endswith(suf):
            try:
                num = float(s[:-len(suf)])
                return int(num*mult)
            except:
                pass
    try:
        return int(s)
    except:
        return s

def get_default_settings():
    prog = os.path.basename(sys.argv[0]).lower()
    default_op = "compress"
    default_stdout = False
    default_format = "xz"
    if "lzcat" in prog:
        default_op = "decompress"
        default_stdout = True
        default_format = "lzma"
    elif "unlzma" in prog:
        default_op = "decompress"
        default_format = "lzma"
    elif prog == "lzma" or prog.endswith("/lzma") or (prog.startswith("lzma") and "xz" not in prog):
        # Also check if basename is exactly lzma
        if prog == "lzma" or prog.endswith("lzma") and "un" not in prog and "cat" not in prog:
            # need more precise: if prog contains lzma and not un and not cat
            if "un" not in prog and "cat" not in prog:
                default_op = "compress"
                default_format = "lzma"
            else:
                default_op = "decompress"
                default_format = "lzma"
        else:
            default_op = "compress"
            default_format = "lzma"
        # More accurate logic from earlier:
        # lzma -> compress lzma
        # unlzma -> decompress lzma
        # lzcat -> decompress lzma stdout
        # So we already handled lzcat and unlzma above
        # If we reach here, it's lzma compress
        if "unlzma" not in prog and "lzcat" not in prog:
            default_op = "compress"
            default_format = "lzma"
    elif "xzcat" in prog:
        default_op = "decompress"
        default_stdout = True
        default_format = "auto"
    elif "unxz" in prog:
        default_op = "decompress"
        default_format = "auto"
    else:
        default_op = "compress"
        default_format = "xz"
    return default_op, default_stdout, default_format

