            default_format = "lzma"
    elif "xzcat" in prog:
        default_op = "decompress"
        default_stdout = True
        default_format = "auto"
    elif "unxz" in prog:
        default_op = "decompress"
        default_format = "auto"
    else:
        default_op = "compress"
        default_format = "xz"
    return default_op, default_stdout, default_format

